% test procedure for the grid function%%by J. Decker (MIT/RLE, jodecker@mit.edu) 11/29/02%modified by Y.Peysson (CEA/DRFC, yves.peysson@cea.fr) 30/01/03%last update 22/07/03%clear allclose all%dke_mode = 0;%or 1Rp_norm = 1;rho_S = [0.05,[0.1:0.2:0.9],0.95];%nmhu_S_in = 132;np_S_in = 124;pnmax_S_in = 10;% in pth unitsrho_display_in = 0.551;%grid_method = input_dke_yp('Pitch-angle grid calculation technique: (0): old method, (1) new method',1);grid_uniformity = input_dke_yp('Pitch-angle and momentum grids uniformity: (0) no, (1) yes',0);%[pn,dpn,pnm,dpnm,pnp,dpnp,pn_S,mhu,dmhu,mhum,dmhum,mhup,dmhup,mhu_S,xia,xrho,xdrho,xrhom,xdrhom,xrhop,xdrhop,xrho_S,rdke,rho_display,ir_display] = grid_dke_yp(grid_method,grid_uniformity,dke_mode,Rp_norm,rho_S,nmhu_S_in,np_S_in,pnmax_S_in,rho_display_in);%Grid calculations%nmhu = length(mhu);;nmhu_S = length(mhu_S);%info_dke_yp(2,'Pitch angle grid vector lengths')disp([int2str(length(mhu)),'/',int2str(length(dmhu)),'/',int2str(length(mhum)),'/',int2str(length(dmhum)),'/',int2str(length(mhup)),'/',int2str(length(dmhup)),'/',int2str(length(mhu_S))])%info_dke_yp(2,'Momentum grid vector lengths')disp([int2str(length(pn)),'/',int2str(length(dpn)),'/',int2str(length(pnm)),'/',int2str(length(dpnm)),'/',int2str(length(pnp)),'/',int2str(length(dpnp)),'/',int2str(length(pn_S))])%info_dke_yp(2,'Radial grid vector lengths')disp([int2str(length(xrho)),'/',int2str(length(xdrho)),'/',int2str(length(xrhom)),'/',int2str(length(xdrhom)),'/',int2str(length(xrhop)),'/',int2str(length(xdrhop)),'/',int2str(length(xrho_S))])%xmhut = sqrt(2*xia./(1+xia));dmhu_ref = 2/(nmhu_S_in-1); % grid step for uniform grid%figure(1),clfhold on%for i=1:length(xmhut),    if abs(xmhut(i)) <= 1,plot([0,xmhut(i)],[0,sqrt(1-xmhut(i)^2)],'r'),endendfor i=1:nmhu,    if abs(mhu(i)) <= 1,plot([0,mhu(i)],[0,sqrt(1 - mhu(i)^2)],'b'),endendfor i=1:nmhu_S,    if abs(mhu_S(i)) <= 1,plot([0,mhu_S(i)],[0,sqrt(1-mhu_S(i)^2)],'g'),endendhold offaxis('equal')ylabel('pperp')xlabel('ppar')zoom on%figure(2),clfplot([1:nmhu]-1+1/2,mhu,'b+',[1:nmhu_S]-1,mhu_S,'rx'),grid on,zoom onylabel('mhu')xlabel('Index')%figure(3),clf%************* A vŽrifier ***********plot([1:nmhu]-1+1/2,dmhu,'b-',[1:nmhu]-1+1/2,dmhu,'bx')hold onfor i=1:length(xmhut)	jmax = max(find(mhu < xmhut(i)));%mhu > 0 	jmin = min(find(mhu > -xmhut(i)));%mhu < 0     jtmax = jmax-1+1/4;	jtmin = jmin-1+1/4;    plot([jtmax,jtmax],[0,dmhu_ref],'r')    plot([jtmin,jtmin],[0,dmhu_ref],'r')endhold offgrid onzoom on%nr = length(xrho);nr_S = length(xrho_S);%figure(4),clfplot([1:nr]-1+1/2,xrho,'b+',[1:nr_S]-1,xrho_S,'rx',[rdke(ir_display)-1+1/2,rdke(ir_display)-1+1/2],[0,1],'g-.',[0,nr],[rho_display,rho_display],'g-.'),grid onylabel('rho')xlabel('Index')zoom on%npn = length(pn);npn_S = length(pn_S);%figure(5),clfplot([1:npn]-1+1/2,pn,'b+',[1:npn_S]-1,pn_S,'rx'),grid onylabel('p')xlabel('Index')zoom on%figure(6),clfmc2 = 510.99905;%Electron energy rest mass (keV)pn_ref = pn;dpn_ref = dpn;pn2_ref = pn_ref.^2;Ten_ref = 1/mc2;betath_ref = sqrt(Ten_ref)z_ref = betath_ref*pn_ref;z2_ref = z_ref.*z_ref;gamma_ref = sqrt(1 + z2_ref);nmhu = length(mhu);dp_cyl = 0.1;fM_ref = exp(-pn_ref.*pn_ref./(1 + gamma_ref))/2/pi/sqrt(2*pi);%Maxwellian distribution normalized to normalized density ne_norm (1st order gamma corrections)XfM_ref = fM_ref'*ones(1,nmhu);normfM_ref = 2*pi*integral_dke_jd(dpn_ref(:),pn_ref(:).*pn_ref(:).*integral_dke_jd(dmhu,XfM_ref,2),1);XfM_ref = XfM_ref/normfM_ref;Xf0_ref = XfM_ref;normf0_ref = 2*pi*integral_dke_jd(dpn_ref(:),pn2_ref(:).*integral_dke_jd(dmhu,Xf0_ref,2),1);[logXf0_cyl_ref,ppar_cyl_ref,dppar_cyl_ref,pperp_cyl_ref,dpperp_cyl_ref] = s2c_dke_yp(log(Xf0_ref),pn_ref,mhu,dp_cyl);Xppar_cyl_ref = ones(length(pperp_cyl_ref),1)*ppar_cyl_ref(:)';Xpperp_cyl_ref = pperp_cyl_ref(:)*ones(1,length(ppar_cyl_ref));Xp_cyl_ref = sqrt(Xppar_cyl_ref.*Xppar_cyl_ref + Xpperp_cyl_ref.*Xpperp_cyl_ref);Xf0_cyl_ref = exp(logXf0_cyl_ref);%For accurate representation in figures Xf0_cyl_ref = Xf0_cyl_ref.*(Xf0_cyl_ref>0);%Remove negative valuesXf0_cyl_ref = Xf0_cyl_ref.*(Xp_cyl_ref<max(ppar_cyl_ref));%Remove values above max(ppar)C = contour(ppar_cyl_ref,pperp_cyl_ref,log(Xf0_cyl_ref),[-20:20/30:0]);axis('equal');faxis = axis;dfaxis_x = (faxis(2) - faxis(1))/100;dfaxis_y = (faxis(4) - faxis(3))/100; xlabel('ppar/pth-ref');ylabel('pperp/pth-ref');pause(0.1);